package com.rikkeibank.transaction.service; import com.rikkeibank.transaction.client.AccountClient; import com.rikkeibank.transaction.dto.*; import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException;
@Service public class AccountClientFacade{private final AccountClient client;private final String key;public AccountClientFacade(AccountClient c,@Value("${app.internal-key}")String key){client=c;this.key=key;}@CircuitBreaker(name="accountService",fallbackMethod="fallback") public AccountBalanceResponse debit(AccountOperationRequest r){return client.debit(key,r);}@CircuitBreaker(name="accountService",fallbackMethod="fallback") public AccountBalanceResponse credit(AccountOperationRequest r){return client.credit(key,r);}@CircuitBreaker(name="accountService",fallbackMethod="fallback") public AccountBalanceResponse compensateDebit(AccountOperationRequest r){return client.compensateDebit(key,r);}@CircuitBreaker(name="accountService",fallbackMethod="fallback") public AccountBalanceResponse compensateCredit(AccountOperationRequest r){return client.compensateCredit(key,r);}public AccountBalanceResponse fallback(AccountOperationRequest r,Throwable ex){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"account-service tạm thời không khả dụng",ex);}}
